-- 2026-11-10: version 68 (document IT-POL-007 "Personal Computer and Room TV - Procurement and Assignment policy") holds its Change History
-- table and its Category/Description table broken into pieces: the table was pasted from Word into the editor, which cut it apart (header row alone, rows with
-- 7 / 4 / 2 cells, the Key Changes bullets loose underneath). This rewrites just those two tables as proper tables; the rest of the content is untouched.
-- (Pasting is fixed in the editor from now on; this repairs the one document already saved that way. UAT has no other document in this state.)
--
-- Run PART 1 first. PART 2 ends in ROLLBACK: change it to COMMIT once the UPDATE says 1 row. A backup of the old content is kept in documentversions_fix_20261110.

-- ===== PART 1: read-only =====
SELECT v.id, v.documentid, d.documentnumber, d.title, length(v.content) AS content_length
FROM DocumentVersions v JOIN Documents d ON d.Id = v.DocumentId
WHERE v.Id = 68 AND v.Content LIKE '%Azfar Sabeeh%' AND v.Content LIKE '<p>Change History</p><table>%';

-- ===== PART 2 =====
BEGIN;
CREATE TABLE IF NOT EXISTS documentversions_fix_20261110 AS SELECT Id, Content, now() AS backed_up_at FROM DocumentVersions WHERE FALSE;
INSERT INTO documentversions_fix_20261110 (Id, Content, backed_up_at)
SELECT Id, Content, now() FROM DocumentVersions WHERE Id = 68 AND Content LIKE '%Azfar Sabeeh%' AND Content LIKE '<p>Change History</p><table>%'
  AND NOT EXISTS (SELECT 1 FROM documentversions_fix_20261110 b WHERE b.Id = 68);

UPDATE DocumentVersions
SET Content = $fixed$<p>Change History</p><table><tbody><tr><td class="ql-align-center"><strong>Version</strong></td><td class="ql-align-center"><strong>Date</strong></td><td class="ql-align-center"><strong>Prepared By</strong></td><td class="ql-align-center"><strong>Approved By</strong></td><td class="ql-align-center"><strong>Key Changes</strong></td></tr><tr><td class="ql-align-center">1.0</td><td class="ql-align-center">Jul 01, 2024</td><td>Azfar Sabeeh</td><td>Ismail Allawala</td><td>Previous version covering procurement and assignment of computers, printers, and room TVs with category-based allocation and operational guidelines.</td></tr><tr><td class="ql-align-center">2.0</td><td class="ql-align-center">May 01, 2026</td><td>Ghayas Siddiqui</td><td>Ismail Allawala</td><td>• Enhanced clarity on asset lifecycle governance and entitlement model • Strengthened positioning of security and compliance controls • Better alignment with audit, inventory, and approval framework.</td></tr><tr><td class="ql-align-center">3.0</td><td class="ql-align-center">Aug 07, 2026</td><td>Ghayas Siddiqui</td><td>Ismail Allawala</td><td>• Updated Room/TV LED Size Model Policy for Director’s enclave and others. • Updated Category B – Officers (Grade s2–s8) • Category C - Grades (s9 - s12) (if Applicable) • Updated CPU: At least 8 Cores</td></tr></tbody></table><p><br></p><p><br></p><h2>1. Introduction</h2><p>This policy defines ATCO’s standards for procurement, allocation, usage, security, replacement, and return of company-owned computers (desktops/laptops), printers, and room TVs/monitors.</p><p>The objective is to:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Ensure employees are equipped with appropriate computing resources</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Maintain information security and regulatory compliance</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Optimize asset utilization and lifecycle management</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Support audit, governance, and business continuity requirements</li></ol><h2>2. Scope &amp; Applicability</h2><p>This policy applies to:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All permanent and contractual employees</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Interns and consultants (where devices are issued)</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All company-owned IT assets listed herein</li></ol><p>Excluded:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Personally owned devices (BYOD), governed separately.</li></ol><h2>3. General Principles</h2><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All devices remain property of ATCO</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Each position is entitled to one primary computing device unless formally approved otherwise</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Devices are issued strictly for official business use</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All assets must be tagged, recorded in IT inventory, and auditable</li></ol><h2>4. Employee Categories</h2><table><tbody><tr><td class="ql-align-center"><strong>Category</strong></td><td class="ql-align-center"><strong>Description</strong></td></tr><tr><td class="ql-align-center">A</td><td>Directors (Grade 1)</td></tr><tr><td class="ql-align-center">B</td><td>Officers (Grade 2–12)</td></tr></tbody></table><h2>5. Device Entitlement &amp; Procurement</h2><p>5.1 Standard Entitlement</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Each eligible employee is entitled to a laptop</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Dual device allocation is not permitted without written exception approval</li></ol><p>5.2 Special Approvals</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Secondary devices (where justified) require:</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>HOD + Head IT + MD approval</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Registration as a secondary asset</li></ol><p>5.3 Procurement Process</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All requests must be raised via IT@atcolab.com</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>IT may issue:</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>New devices</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Refurbished devices (meeting specifications)</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Reallocated inventory assets</li></ol><h2>6. Security &amp; Compliance Requirements (Mandatory)</h2><p>All issued devices must comply with the following:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Endpoint protection anti-virus managed by IT</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Automatic screen lock enforced</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>No local administrator rights unless approved</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>USB and removable media controls (as per IT Security Policy)</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>IT reserves the right to:</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Audit devices at any time</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Remotely lock or wipe devices in case of loss or risk</li></ol><h2>7. Replacement &amp; Upgrade Policy</h2><p>Devices may be replaced or upgraded based on:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Hardware age ≥ 3 years</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Performance limitations confirmed by IT</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Physical damage beyond economical repair</li></ol><p>All replaced assets must be returned to IT with accessories.</p><h2>8. Loss or Theft of Laptop</h2><p>In case of loss or theft:</p><ol><li data-list="ordered" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Employee must immediately notify IT and HR</li><li data-list="ordered" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Police report is mandatory</li><li data-list="ordered" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>HR &amp; IT will assess negligence</li><li data-list="ordered" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Replacement processed per entitlement rules</li></ol><h2>9. User Responsibilities</h2><p>Employees must:</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Use devices strictly for official purposes</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Not share devices with any unauthorized person</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Avoid storing illegal or inappropriate content</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Secure devices during travel</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Return devices during separation after data verification from line manager</li></ol><h2>10. Printers</h2><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Shared printers are the default standard</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>All printers remain under IT ownership and inventory control</li></ol><h2>11. Room Tv / Monitor</h2><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Eligible: Grade 2 and above</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Purpose: Meetings and presentations</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Except for MD, all directors in Director’s enclave to be eligible to Room TV “<strong>TCL 43T6C”. </strong>For rest, decision to be made by Head of IT based on room size.</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Requests must be submitted via <strong>official email</strong> with <strong>approval from HOD and MD</strong>.</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>TVs/Monitors are fixed assets under IT custody</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Any deviation from the above will require additional approval from MD. </li></ol><h2>12. Audit &amp; Governance</h2><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>IT maintains a central asset register</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Policy violations may result in disciplinary action</li></ol><h2>Annexure A</h2><p>CATEGORY-WISE TECHNICAL SPECIFICATIONS (2026)</p><p>Category A – Directors (Grade s1)</p><ol><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Device: Laptop</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>CPU: At least 8 Cores</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>RAM: 16–32 GB</li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Storage: 1TB SSD </li><li data-list="bullet" class="ql-indent-1"><span class="ql-ui" contenteditable="false"></span>Accessories: Wireless mouse, bag, charger</li></ol><p>Category B – Officers (Grade s2–s8)</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Device: Laptop</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>CPU: At least 8 Cores</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>RAM: 16 GB</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Storage: 1 TB SSD</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Accessories: Wireless mouse, bag, charger</li></ol><p>Category C – Grades (s9 - s12) (if Applicable)</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Device: Laptop</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>CPU: At least 8 Cores</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>RAM: 16 GB</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Storage: 1 TB SSD</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Accessories: Wireless mouse, bag, charger</li></ol><h2><br></h2><p>                                           </p>$fixed$
WHERE Id = 68 AND Content LIKE '%Azfar Sabeeh%' AND Content LIKE '<p>Change History</p><table>%';
-- expect: UPDATE 1

SELECT Id, length(Content) FROM DocumentVersions WHERE Id = 68;
ROLLBACK;
